{"content": "#!/usr/bin/env python3
"""Rebuild index.md with proper counts, descriptions, and all sections."""
import os, re, glob

wiki = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki"

# Read frontmatter descriptions from all existing wiki pages
def get_page_info(fpath):
    with open(fpath, encoding="utf-8") as f:
        content = f.read()
    fm_match = re.search(r'^---\n(.*?)\n---', content, re.DOTALL)
    if not fm_match:
        return None, None
    fm = fm_match.group(1)

    title = None
    summary = None
    for line in fm.split('\n'):
        if line.startswith('title:'):
            title = line.split(':', 1)[1].strip().strip('"').strip("'")
        if line.startswith('summary:'):
            summary = line.split(':', 1)[1].strip().strip('"').strip("'")
    return title, summary

def get_subdir_pages(subdir):
    pages = []
    d = os.path.join(wiki, "wiki", subdir)
    if not os.path.isdir(d):
        return pages
    for f in sorted(os.listdir(d)):
        if not f.endswith('.md') or f == '.gitkeep':
            continue
        slug = f[:-3]  # remove .md
        title, summary = get_page_info(os.path.join(d, f))
        pages.append((slug, title or slug, summary or ""))
    return pages

# Gather pages by type
sources = get_subdir_pages("sources")
entities = get_subdir_pages("entities")
concepts = get_subdir_pages("concepts")
comparisons = get_subdir_pages("comparisons")
overviews = get_subdir_pages("overview")
queries = get_subdir_pages("queries")

total = len(sources) + len(entities) + len(concepts) + len(comparisons) + len(overviews) + len(queries)

lines = []
lines.append("# YouTube Video Research Wiki")
lines.append(f"Last updated: 2026-05-12")
lines.append(f"Total pages: {total}")
lines.append("")

# Sources
lines.append("## Sources")
for slug, title, summary in sources:
    if summary:
        lines.append(f"- [[{slug}|{title}]] — {summary}")
    else:
        lines.append(f"- [[{slug}|{title}]]")
lines.append("")

# Entities
lines.append("## Entities")
for slug, title, summary in entities:
    if summary:
        lines.append(f"- [[{slug}|{title}]] — {summary}")
    else:
        lines.append(f"- [[{slug}|{title}]]")
lines.append("")

# Concepts
lines.append("## Concepts")
for slug, title, summary in concepts:
    if summary:
        lines.append(f"- [[{slug}|{title}]] — {summary}")
    else:
        lines.append(f"- [[{slug}|{title}]]")
lines.append("")

# Comparisons (if any)
if comparisons:
    lines.append("## Comparisons")
    for slug, title, summary in comparisons:
        if summary:
            lines.append(f"- [[{slug}|{title}]] — {summary}")
        else:
            lines.append(f"- [[{slug}|{title}]]")
    lines.append("")

# OverViews
if overviews:
    lines.append("## OverViews")
    for slug, title, summary in overviews:
        if summary:
            lines.append(f"- [[{slug}|{title}]] — {summary}")
        else:
            lines.append(f"- [[{slug}|{title}]]")
    lines.append("")

# Queries
if queries:
    lines.append("## Queries")
    for slug, title, summary in queries:
        if summary:
            lines.append(f"- [[{slug}|{title}]] — {summary}")
        else:
            lines.append(f"- [[{slug}|{title}]]")
    lines.append("")

result = "\n".join(lines)
with open(os.path.join(wiki, "index.md"), "w", encoding="utf-8") as f:
    f.write(result)

print(f"Total pages: {total} (SRC={len(sources)}, ENT={len(entities)}, CON={len(concepts)}, CMP={len(comparisons)}, OVR={len(overviews)}, QRY={len(queries)})")
print("✅ index.md rebuilt")
